#!/bin/sh
# generated by cluster/overnight.py
cd "$HOME/universe-1" || exit 1
mkdir -p results/life
S=results/life/overnight_status.txt
echo "$(date -u +%FT%TZ) overnight.sh started on $(hostname)" >> $S
(
  while pgrep -f "^python3 cluster/exp06b_node.py" >/dev/null 2>&1; do sleep 60; done
  mkdir -p results/life/jc_long_s1
  echo "$(date -u +%FT%TZ) start jc_long_s1 slot 0" >> $S
  nice -n 10 life/u1life_cuda --gpu 0 --isa SWAP,ADD,NAND,JC --N 1024 --seed 1 --ticks 4500000 --report-every 1000 --income 20 --ppm-every 5000 --out-dir results/life/jc_long_s1 --dump-final > results/life/jc_long_s1/run.log 2>&1
  echo "$(date -u +%FT%TZ) end jc_long_s1 exit $?" >> $S
) &
(
  while pgrep -f "^python3 cluster/exp06b_node.py" >/dev/null 2>&1; do sleep 60; done
  mkdir -p results/life/jc_long_s2
  echo "$(date -u +%FT%TZ) start jc_long_s2 slot 1" >> $S
  nice -n 10 life/u1life_cuda --gpu 1 --isa SWAP,ADD,NAND,JC --N 1024 --seed 2 --ticks 4500000 --report-every 1000 --income 20 --ppm-every 5000 --out-dir results/life/jc_long_s2 --dump-final > results/life/jc_long_s2/run.log 2>&1
  echo "$(date -u +%FT%TZ) end jc_long_s2 exit $?" >> $S
) &
(
  while pgrep -f "^python3 cluster/exp06b_node.py" >/dev/null 2>&1; do sleep 60; done
  mkdir -p results/life/jc_s3
  echo "$(date -u +%FT%TZ) start jc_s3 slot 2" >> $S
  nice -n 10 life/u1life_cuda --gpu 2 --isa SWAP,ADD,NAND,JC --N 1024 --seed 3 --ticks 200000 --report-every 1000 --income 20 --ppm-every 100 --out-dir results/life/jc_s3 --dump-final > results/life/jc_s3/run.log 2>&1
  echo "$(date -u +%FT%TZ) end jc_s3 exit $?" >> $S
  mkdir -p results/life/jc_long_mu512
  echo "$(date -u +%FT%TZ) start jc_long_mu512 slot 2" >> $S
  nice -n 10 life/u1life_cuda --gpu 2 --isa SWAP,ADD,NAND,JC --N 1024 --seed 1 --ticks 4000000 --report-every 1000 --income 20 --mu-bits 512 --ppm-every 5000 --out-dir results/life/jc_long_mu512 --dump-final > results/life/jc_long_mu512/run.log 2>&1
  echo "$(date -u +%FT%TZ) end jc_long_mu512 exit $?" >> $S
) &
(
  mkdir -p results/life/cpu_champ512_512_s1
  echo "$(date -u +%FT%TZ) start cpu_champ512_512_s1 slot cpu" >> $S
  nice -n 19 life/u1life_cpu --isa SWAP,ADD,NAND,SKZ --N 512 --seed 1 --ticks 1000000 --report-every 1000 --income 36 --max-steps 512 --ppm-every 3000 --threads 16 --out-dir results/life/cpu_champ512_512_s1 --dump-final > results/life/cpu_champ512_512_s1/run.log 2>&1
  echo "$(date -u +%FT%TZ) end cpu_champ512_512_s1 exit $?" >> $S
) &
wait
echo "$(date -u +%FT%TZ) overnight.sh finished" >> $S
